---
import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"section"> & VariantProps<typeof variants>

const variants = cva("gap-16 py-[var(--section-padding,--spacing(16))] relative flex scroll-mt-12 flex-col", {
  variants: {
    variant: {
      default: "bg-background w-full",
      floating:
        "bg-background my-16 rounded-xl border shadow-md mx-auto w-[calc(100%-2*var(--gutter,--spacing(4)))] max-w-[calc(var(--container,var(--container-7xl))-2*var(--gutter,--spacing(4)))] overflow-hidden",
    },
  },
  defaultVariants: {
    variant: "default",
  },
})

const { class: className, variant, ...props } = Astro.props
---

<section
  class={cn(variants({ variant }), className)}
  data-slot="section"
  data-variant={variant}
  {...props}
>
  <slot />
</section>

---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"div">

const {
  class: className,
  "data-slot": dataSlot = "section-container",
  ...props
} = Astro.props
---

<div
  data-slot={dataSlot}
  class={cn(
    "relative mx-auto flex w-full max-w-[var(--container,var(--container-7xl))] flex-col gap-8 px-[var(--gutter,--spacing(4))]",
    className
  )}
  {...props}
>
  <slot />
</div>
